#include <iostream>
#include <memory>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Animal {
public:
    explicit Animal(std::string name) : name_(std::move(name)) {}
    virtual ~Animal() = default;

    const std::string &name() const {
        return name_;
    }

    virtual std::string kind() const = 0;
    virtual std::string sound() const = 0;

private:
    std::string name_;
};

class Cat : public Animal {
public:
    using Animal::Animal;

    std::string kind() const override {
        return "кошка";
    }

    std::string sound() const override {
        return "мяу";
    }
};

class Dog : public Animal {
public:
    using Animal::Animal;

    std::string kind() const override {
        return "собака";
    }

    std::string sound() const override {
        return "гав";
    }
};

class Parrot : public Animal {
public:
    using Animal::Animal;

    std::string kind() const override {
        return "попугай";
    }

    std::string sound() const override {
        return "привет";
    }
};

int main() {
    std::vector<std::unique_ptr<Animal>> zoo;
    std::string kind, name;
    while (std::cin >> kind >> name) {
        if (kind == "cat") {
            zoo.push_back(std::make_unique<Cat>(name));
        } else if (kind == "dog") {
            zoo.push_back(std::make_unique<Dog>(name));
        } else {
            zoo.push_back(std::make_unique<Parrot>(name));
        }
    }
    for (const auto &a : zoo) {
        std::println("{} ({}): {}", a->name(), a->kind(), a->sound());
    }
    std::println("животных {}", zoo.size());
    return 0;
}

