#include <iostream>
#include <memory>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Job {
public:
    explicit Job(std::string name) : name_(std::move(name)) {}

    virtual ~Job() {
        std::println("~Job {}", name_);
    }

protected:
    const std::string &name() const {
        return name_;
    }

private:
    std::string name_;
};

class Backup : public Job {
public:
    using Job::Job;

    ~Backup() override {
        std::println("~Backup {}", name());
    }
};

class Report : public Job {
public:
    using Job::Job;

    ~Report() override {
        std::println("~Report {}", name());
    }
};

int main() {
    std::vector<std::unique_ptr<Job>> jobs;
    std::string command;
    while (std::cin >> command) {
        if (command == "stop") {
            std::println("остановка");
            jobs.clear();
            continue;
        }
        if (command == "done") {
            long long i;
            std::cin >> i;
            if (i < 1 || i > static_cast<long long>(jobs.size())) {
                std::println("нет задания {}", i);
            } else {
                jobs.erase(jobs.begin() + (i - 1));
            }
            continue;
        }
        std::string name;
        std::cin >> name;
        if (command == "backup") {
            jobs.push_back(std::make_unique<Backup>(name));
        } else if (command == "report") {
            jobs.push_back(std::make_unique<Report>(name));
        } else {
            jobs.push_back(std::make_unique<Job>(name));
        }
    }
    std::println("конец");
    return 0;
}

