struct T {
    int id;
    explicit T(int id) : id(id) {}
    virtual ~T() { std::print("{} ", id); }
};

int main() {
    std::vector<std::unique_ptr<T>> v;
    for (int i = 1; i <= 3; i++) {
        v.push_back(std::make_unique<T>(i));
    }
    v.erase(v.begin());
    std::print("| ");
    v.clear();
    std::println();
    return 0;
}
